import { revalidatePath } from 'next/cache'
import { createClient } from '@/utils/supabase/server'
import { createAdminClient } from '@/utils/supabase/admin'

export async function addBookmark(formData: FormData) {
  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) {
    throw new Error('Not authenticated')
  }

  // Verify profile exists (satisfies foreign key)
  const { data: profile } = await supabase
    .from('profiles')
    .select('id, handle')
    .eq('id', user.id)
    .single()

  if (!profile) {
    // Attempt to "auto-repair" missing profile for existing users
    const supabaseAdmin = createAdminClient()
    const fallbackHandle = `user_${user.id.substring(0, 8)}`

    const { error: repairError } = await supabaseAdmin.from('profiles').insert({
      id: user.id,
      handle: fallbackHandle
    })

    if (repairError) {
      throw new Error('Your user profile is missing. Please contact support or try signing up again.')
    }
  }

  const title = formData.get('title') as string
  const url = formData.get('url') as string
  const is_public = formData.get('is_public') === 'on'

  const { error } = await supabase.from('bookmarks').insert({
    user_id: user.id,
    title,
    url,
    is_public,
  })

  if (error) {
    throw new Error(error.message)
  }

  revalidatePath('/dashboard')
}

